<template>
  <div v-if="tournament" class="t-content">
    <header class="t-page-head"><small class="t-eyebrow">{{tournament.edition}} · {{tournament.game}}</small><h1>{{title}}</h1><p class="t-sub">{{tournament.dateLabel}} · {{tournament.server}} · {{tournament.entry}}</p></header>
    <template v-if="page==='overview'">
      <div class="t-toolbar"><label>Preview registration state <select v-model="registrationPreview"><option value="">Use event configuration</option><option value="open">Open preview</option><option value="closed">Closed preview</option></select></label></div>
      <section :class="['t-registration',registrationStatus]"><div><h2>{{registrationTitle}}</h2><p>{{registrationCopy}}</p></div><RouterLink v-if="registrationStatus==='open'" class="t-button t-primary" :to="path('register')">Preview registration</RouterLink><RouterLink v-else class="t-button" :to="path('teams')">View teams preview</RouterLink></section>
      <div class="t-heading"><h2>Live now</h2><RouterLink :to="path('matches')">All matches →</RouterLink></div><div class="t-grid three"><TournamentMatchCard v-for="match in tournament.matches.slice(0,3)" :key="match.id" :match="match" :tournament="tournament"/></div>
      <div class="t-split"><section><div class="t-heading"><h2>Respawn Broadcast</h2><RouterLink :to="path('broadcast')">Open broadcast →</RouterLink></div><div class="t-player"><span class="t-eyebrow">Official broadcast preview</span><strong>{{tournament.name}}</strong><button @click="notice='Broadcast area preview only. No stream is live in this demo.'">▷ Preview player</button><small>No live feed connected</small></div><p class="t-sub">Now featuring: {{matchLabel(tournament.matches[0])}} · Simulated Game 2</p></section><section><div class="t-heading"><h2>Coming up</h2></div><div class="t-card"><div v-for="match in tournament.matches.filter(m=>m.status==='Upcoming')" :key="match.id" class="t-list"><strong>{{matchLabel(match)}}</strong><p class="t-sub">{{match.round}}<br>{{match.time}}</p><RouterLink :to="path('matches/'+match.id)">View match →</RouterLink></div></div><div class="t-heading"><h2>Latest results</h2></div><div class="t-card"><p v-for="match in tournament.matches.filter(m=>m.status==='Completed')" :key="match.id" class="t-sub">{{matchLabel(match)}} <strong>{{match.score}}</strong></p></div></section></div>
      <div class="t-heading"><h2>Partner coverage</h2><RouterLink :to="path('partner-streams')">All streams →</RouterLink></div><div class="t-grid three"><article v-for="stream in tournament.streams" :key="stream.creator" class="t-card"><span class="t-badge live">Stream preview</span><h3>{{stream.creator}}</h3><p class="t-sub">{{matchLabel(findMatch(stream.matchId))}}<br>{{stream.type}} · {{stream.language}}</p><RouterLink class="t-button" :to="path('matches/'+stream.matchId)">View match</RouterLink></article></div>
    </template>
    <template v-else-if="page==='teams'"><div class="t-toolbar"><input v-model="search" aria-label="Search teams" placeholder="Search teams or creators"></div><div class="t-grid three"><article v-for="team in filteredTeams" :key="team.id" class="t-card"><div class="t-team-head"><div class="t-crest" :style="{color:team.color,borderColor:team.color}">{{team.initials}}</div><div><h3>{{team.name}}</h3><p class="t-sub">{{team.creator}}'s community</p></div></div><div class="t-stats"><span>Seed <strong>#{{team.seed}}</strong></span><span>Record <strong>{{team.record}}</strong></span><span>Lineup <strong>5 + 2</strong></span></div><p class="t-sub">Sample tournament entry · Not a confirmed team</p><RouterLink v-if="team.teamHubSlug" class="t-button" :to="{name:'team-hub-team',params:{teamSlug:team.teamHubSlug}}">Open existing Team Hub</RouterLink><button v-else @click="notice=team.name+' has no linked Team Hub in these fixtures. No duplicate team-management page is created.'">Team information</button><p v-if="team.teamHubSlug" class="t-sub">Your existing Team Hub currently requires sign-in. Access rules are unchanged.</p></article></div><p v-if="!filteredTeams.length" class="t-empty">No teams match your search.</p></template>
    <template v-else-if="page==='matches'"><div class="t-tabs"><button v-for="status in ['All','Live','Drafting','Upcoming','Completed']" :key="status" :class="{selected:filter===status}" @click="filter=status">{{status}}</button></div><div class="t-toolbar"><input v-model="search" aria-label="Search matches" placeholder="Find a team or match"></div><div class="t-grid three"><TournamentMatchCard v-for="match in filteredMatches" :key="match.id" :match="match" :tournament="tournament"/></div><p v-if="!filteredMatches.length" class="t-empty">No matching fixtures.</p></template>
    <template v-else-if="page==='drafts'"><p class="t-callout">Intentional public hovers are visible to both teams and spectators. Private notes and chat stay private.</p><div class="t-tabs"><button v-for="status in ['Drafting','Upcoming','Completed']" :key="status" :class="{selected:filter===status}" @click="filter=status">{{status==='Drafting'?'Live drafts':status}}</button></div><div class="t-grid two"><article v-for="match in tournament.matches.filter(m=>m.status===(filter==='All'?'Drafting':filter))" :key="match.id" class="t-card"><span class="t-badge">{{match.status}} · Demo</span><h3>{{matchLabel(match)}}</h3><p class="t-sub">{{match.round}} · Game {{match.game}}</p><RouterLink class="t-button" :to="path('drafts/'+match.id)">{{match.status==='Completed'?'View draft archive':'Open draft preview'}}</RouterLink></article></div></template>
    <template v-else-if="page==='broadcast'"><div class="t-split"><section><div class="t-player large"><span class="t-eyebrow">Official Project Respawn broadcast</span><strong>{{tournament.name}}</strong><button @click="notice='Demo player: official video and VODs will use approved stream configuration.'">▷ Preview broadcast</button><small>No live feed connected</small></div><h3 class="t-spaced">{{matchLabel(tournament.matches[0])}}</h3><p class="t-sub">Featured match preview · Upper bracket, Round 2</p><RouterLink class="t-button" :to="path('matches/m1')">View featured match</RouterLink><div class="t-heading"><h2>On the desk</h2></div><div class="t-grid three"><article v-for="role in ['Host','Play-by-play','Analyst']" :key="role" class="t-card"><span class="t-eyebrow">{{role}}</span><h3>Talent to be confirmed</h3></article></div></section><section class="t-card"><h2>Running order</h2><div v-for="(match,i) in tournament.matches.slice(0,3)" :key="match.id" class="t-list"><span class="t-eyebrow">{{i===0?'Featured':'Other active match'}}</span><h3>{{matchLabel(match)}}</h3><RouterLink :to="path('matches/'+match.id)">View match →</RouterLink></div><RouterLink class="t-button" :to="path('partner-streams')">Find partner coverage</RouterLink></section></div></template>
    <template v-else-if="page==='streams'"><p class="t-callout">Approved partner streams will be grouped by the match they cover. These are sample creators, not live broadcasts.</p><div class="t-grid three"><article v-for="stream in tournament.streams" :key="stream.creator" class="t-card"><div class="t-player compact"><span class="t-eyebrow">Community coverage preview</span><strong>{{stream.creator}}</strong><button @click="notice='Partner player preview. No real stream is connected.'">▷ Preview stream</button></div><h3 class="t-spaced">{{stream.creator}}</h3><p class="t-sub">{{matchLabel(findMatch(stream.matchId))}}<br>{{stream.language}} · {{stream.type}}<br>Viewer count unavailable in preview</p><RouterLink class="t-button" :to="path('matches/'+stream.matchId)">Open match</RouterLink></article></div></template>
    <template v-else-if="page==='bracket'"><div class="t-tabs"><button v-for="tab in ['Bracket','Standings','Game results']" :key="tab" :class="{selected:bracketTab===tab}" @click="bracketTab=tab">{{tab}}</button></div><template v-if="bracketTab==='Bracket'"><p class="t-callout">Illustrative double-elimination layout. Final tournament format and progression have not been confirmed.</p><h2>Upper bracket</h2><div class="t-bracket"><section v-for="round in bracketRounds" :key="round.title" class="t-round"><h3>{{round.title}}</h3><RouterLink v-for="item in round.matches" :key="item.label" class="t-card" :to="path('matches/'+item.id)"><div v-for="row in item.rows" :key="row[0]" class="t-bracket-row"><span>{{row[0]}}</span><strong>{{row[1]}}</strong></div><small>{{item.label}}</small></RouterLink></section></div><h2 class="t-spaced">Lower bracket</h2><div class="t-card"><h3>Pixel Knights vs Echo Esports</h3><p class="t-sub">Sample lower-bracket match · Winner continues to the next lower round.</p><RouterLink class="t-button" :to="path('matches/m3')">View match preview</RouterLink></div></template><div v-else-if="bracketTab==='Standings'" class="t-card t-table"><table><thead><tr><th>Seed</th><th>Team</th><th>Series record</th><th>Entry</th></tr></thead><tbody><tr v-for="team in tournament.teams" :key="team.id"><td>#{{team.seed}}</td><td>{{team.name}}</td><td>{{team.record}}</td><td>Sample data</td></tr></tbody></table></div><div v-else class="t-grid two"><TournamentMatchCard v-for="match in tournament.matches.filter(m=>m.status==='Completed')" :key="match.id" :match="match" :tournament="tournament"/></div></template>
    <template v-else-if="page==='news'"><div class="t-grid three"><article v-for="article in tournament.news" :key="article.id" class="t-card"><div class="t-news-title">{{article.category}}</div><h3>{{article.title}}</h3><p class="t-sub">{{article.text}}</p><button @click="selectedArticle=article">Read sample article</button></article></div></template>
    <template v-else-if="page==='info'"><div class="t-grid four"><article v-for="item in [[ 'Server',tournament.server],['Entry',tournament.entry],['Format',tournament.format.label],['Draft',tournament.format.draft]]" :key="item[0]" class="t-card"><span class="t-eyebrow">{{item[0]}}</span><h3>{{item[1]}}</h3></article></div><div class="t-heading"><h2>Tournament handbook</h2></div><div class="t-card"><details v-for="(rule,index) in rules" :key="rule[0]" :open="index===0"><summary>{{rule[0]}}</summary><p class="t-sub">{{rule[1]}}</p></details></div></template>
    <template v-else-if="page==='match'"><template v-if="selectedMatch"><TournamentMatchCard :match="selectedMatch" :tournament="tournament"/><div class="t-actions"><RouterLink class="t-button" :to="path('drafts/'+selectedMatch.id)">Watch draft preview</RouterLink><RouterLink class="t-button" :to="path('broadcast')">Official coverage</RouterLink><RouterLink class="t-button" :to="path('partner-streams')">Partner streams</RouterLink><RouterLink class="t-button" :to="path('matches/'+selectedMatch.id+'/lobby')">Participant lobby preview</RouterLink></div><div class="t-heading"><h2>Game-by-game record</h2></div><div class="t-tabs"><button v-for="game in [1,2,3]" :key="game" :class="{selected:gameTab===game}" @click="gameTab=game">Game {{game}}</button></div><div class="t-card"><h3>Game {{gameTab}} · Sample record</h3><p class="t-sub">Sides, approved result and the draft archive belong to this game. No result has been submitted.</p><RouterLink class="t-button" :to="path('drafts/'+selectedMatch.id)">Open draft record</RouterLink></div></template><p v-else class="t-empty">Match not found in this tournament.</p></template>
    <template v-else-if="page==='draft'"><template v-if="selectedMatch"><p class="t-callout">Spectator simulation only. Selecting a champion below changes the public-hover preview, not a real draft.</p><div class="t-draft"><section class="t-draft-team"><h3>{{teamName(selectedMatch.a)}} · Blue</h3><div v-for="(champ,index) in bluePicks" :key="index" :class="['t-pick',{hovering:index===2}]"><strong>{{index===2?hover:champ}}</strong><small>{{index===2&&!locked?'HOVERING':'LOCKED'}} · {{roles[index]}}</small></div></section><section class="t-draft-center"><span class="t-eyebrow">{{locked?'Pick confirmed':'Blue pick phase · Demo'}}</span><div class="t-timer">{{locked?'✓':'24'}}</div><div class="t-champions"><button v-for="champ in champions" :key="champ" :disabled="exclusions.includes(champ)" :class="{excluded:exclusions.includes(champ)}" @click="hover=champ;locked=false">{{champ}}</button></div><button class="t-primary t-spaced" @click="locked=!locked">{{locked?'Reset hover':'Simulate lock in'}}</button><p class="t-sub">Public event: {{locked?'Locked':'Hovered'}} {{hover}}<br>Private messages are not shown.</p></section><section class="t-draft-team red"><h3>{{teamName(selectedMatch.b)}} · Red</h3><div v-for="(champ,index) in redPicks" :key="index" class="t-pick"><strong>{{champ}}</strong><small>LOCKED · {{roles[index]}}</small></div></section></div><div class="t-grid two t-spaced"><div class="t-card"><h3>Sample bans</h3><p class="t-sub">Blue: Poppy · Syndra · Yasuo<br>Red: Rakan · Ezreal · Teemo</p></div><div class="t-card"><h3>Fearless exclusions</h3><p class="t-sub">{{exclusions.join(' · ')}}<br>Illustrative strict-fearless variant; final rules to be confirmed.</p></div></div></template><p v-else class="t-empty">Draft not found in this tournament.</p></template>
    <template v-else-if="page==='registration'"><p class="t-callout">Form preview only. Applications are not open and nothing is saved or submitted.</p><form class="t-card t-form" @submit.prevent="notice='Demo application complete. Nothing was sent or saved.'"><label>Creator representative<input required placeholder="Creator name"></label><label>Team name<input required placeholder="Team Hub team"></label><label>Lineup<select><option>Sample Team Hub lineup · Five starters + substitutes</option></select></label><label class="t-check"><input required type="checkbox"> I have reviewed the tournament information.</label><button class="t-primary">Preview submission</button></form></template>
    <template v-else-if="page==='lobby'"><p class="t-callout">Participant workflow preview only. Real check-in, side selection and submission will require backend-authorised access.</p><div class="t-grid two"><div class="t-card"><h3>Check-in & lineup</h3><p class="t-sub">Approved players selected from Team Hub. No duplicate roster management.</p><button @click="ready=!ready">{{ready?'✓ Team ready · Demo':'Mark team ready · Demo'}}</button></div><div class="t-card"><h3>Side selection</h3><p class="t-sub">Higher seed chooses Game 1; previous-game loser chooses thereafter.</p><div class="t-actions"><button @click="side='Blue'">Blue side</button><button @click="side='Red'">Red side</button></div><p class="t-sub">{{side?side+' side selected in preview.':'Awaiting selection.'}}</p><RouterLink class="t-button" :to="path('drafts/'+$route.params.matchId)">Enter draft preview</RouterLink></div></div><div class="t-actions"><button @click="notice='Result submission preview only. Real results need opponent confirmation or administrator approval.'">Result submission preview</button><button @click="notice='Admin support preview only. No message was sent.'">Contact admin preview</button></div></template>
    <div v-if="notice||selectedArticle" class="t-modal-backdrop" @click.self="dismiss"><section role="dialog" aria-modal="true" aria-labelledby="t-dialog-title" class="t-dialog" @keydown.esc="dismiss"><button ref="dialogClose" aria-label="Close preview dialog" class="t-close" @click="dismiss">×</button><h2 id="t-dialog-title">{{selectedArticle?selectedArticle.title:'Demo preview'}}</h2><p class="t-sub">{{selectedArticle?selectedArticle.text:notice}}</p><p v-if="selectedArticle" class="t-sub">Sample editorial preview. Event-specific announcements will be supplied by the tournament configuration or its future news adapter.</p></section></div>
  </div>
</template>
<script src="./TournamentPageContent.js"></script>
<style src="./TournamentPageContent.css"></style>
